// lib/eval/retrievers.ts
// Deterministic, offline retrievers used by the browser demo.
//
// IMPORTANT TRADEOFF (see README): the public demo cannot download embedding
// models or call an API, so "dense" here is a TF-IDF vector-space proxy, not a
// neural embedder. The architecture (sparse / dense / RRF hybrid / rerank) and
// the harness mechanics are real and reproducible; the absolute numbers are
// meant to be regenerated by backend/ with a real embedding model.

function normalise(text: string): string {
  return text
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function tokenize(text: string): string[] {
  return normalise(text)
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

export type Retriever = (query: string, k: number) => string[];

/** Sparse lexical retrieval (Okapi BM25). */
export function bm25Retriever(
  corpus: readonly { id: string; text: string }[],
  options: { k1?: number; b?: number } = {},
): Retriever {
  const { k1 = 0.9, b = 0.4 } = options;
  const docs = corpus.map((c) => tokenize(c.text));
  const N = docs.length || 1;
  const avgdl = docs.reduce((s, d) => s + d.length, 0) / N || 1;
  const df = new Map<string, number>();
  docs.forEach((d) => new Set(d).forEach((t) => df.set(t, (df.get(t) ?? 0) + 1)));
  const idf = (t: string): number => {
    const n = df.get(t) ?? 0;
    return Math.log((N - n + 0.5) / (n + 0.5) + 1);
  };

  return (query: string, k: number): string[] => {
    const qTerms = new Set(tokenize(query));
    return corpus
      .map((chunk, i) => {
        const tokens = docs[i];
        const tf = new Map<string, number>();
        tokens.forEach((t) => tf.set(t, (tf.get(t) ?? 0) + 1));
        let score = 0;
        for (const term of qTerms) {
          const f = tf.get(term) ?? 0;
          if (f === 0) continue;
          score += idf(term) * ((f * (k1 + 1)) / (f + k1 * (1 - b + (b * tokens.length) / avgdl)));
        }
        return { id: chunk.id, score };
      })
      .filter((r) => r.score > 0)
      .sort((a, b2) => b2.score - a.score)
      .slice(0, k)
      .map((r) => r.id);
  };
}

function tfidfVector(text: string, df: Map<string, number>, N: number): Map<string, number> {
  const tokens = tokenize(text);
  const tf = new Map<string, number>();
  tokens.forEach((t) => tf.set(t, (tf.get(t) ?? 0) + 1));
  const vec = new Map<string, number>();
  tf.forEach((count, term) => {
    const idf = Math.log((N + 1) / ((df.get(term) ?? 0) + 1)) + 1;
    vec.set(term, (count / tokens.length) * idf);
  });
  // L2 normalise
  let norm = 0;
  vec.forEach((v) => (norm += v * v));
  norm = Math.sqrt(norm) || 1;
  vec.forEach((v, term) => vec.set(term, v / norm));
  return vec;
}

function cosine(a: Map<string, number>, b: Map<string, number>): number {
  const [small, large] = a.size < b.size ? [a, b] : [b, a];
  let dot = 0;
  small.forEach((v, term) => {
    const other = large.get(term);
    if (other !== undefined) dot += v * other;
  });
  return dot;
}

/** Vector-space cosine retrieval (TF-IDF proxy for a dense embedder). */
export function tfidfRetriever(corpus: readonly { id: string; text: string }[]): Retriever {
  const N = corpus.length || 1;
  const df = new Map<string, number>();
  corpus.forEach((c) =>
    new Set(tokenize(c.text)).forEach((t) => df.set(t, (df.get(t) ?? 0) + 1)),
  );
  const docVectors = corpus.map((c) => tfidfVector(c.text, df, N));

  return (query: string, k: number): string[] => {
    const queryVector = tfidfVector(query, df, N);
    return corpus
      .map((chunk, i) => ({ id: chunk.id, score: cosine(queryVector, docVectors[i]) }))
      .filter((r) => r.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, k)
      .map((r) => r.id);
  };
}

/** Reciprocal Rank Fusion — merges ranked lists without score calibration. */
export function reciprocalRankFusion(
  sources: readonly Retriever[],
  corpus: readonly { id: string }[],
  rrfK = 60,
  depth = 100,
): Retriever {
  return (query: string, k: number): string[] => {
    const scores = new Map<string, number>();
    for (const source of sources) {
      source(query, depth).forEach((id, rank) => {
        scores.set(id, (scores.get(id) ?? 0) + 1 / (rrfK + rank + 1));
      });
    }
    // Tie-break by corpus order for reproducibility.
    const order = new Map(corpus.map((c, i) => [c.id, i]));
    return [...scores.entries()]
      .sort((a, b) => b[1] - a[1] || (order.get(a[0]) ?? 0) - (order.get(b[0]) ?? 0))
      .slice(0, k)
      .map(([id]) => id);
  };
}
